package com.ruoyi.ai.agent;
import com.ruoyi.ai.domain.dto.*;
import com.ruoyi.ai.mapper.AiWorkbookMapper;
import com.ruoyi.common.core.domain.R;
import com.ruoyi.common.core.context.SecurityContextHolder;
import junit.framework.TestCase;
import java.util.*;
import java.lang.reflect.*;

public class B10BranchBoundaryMysqlTest extends TestCase {
    private A1TestFixture f;private long book,main,target;private String head;private final String a="{\"v\":1}",b="{\"v\":2}",c="{\"v\":3}";
    protected void setUp() throws Exception {f=new A1TestFixture(true);book=f.seed("{\"v\":0}");f.identity();Map<String,Object>s=f.status(book);main=((Number)s.get("branchId")).longValue();CommitRequest r=new CommitRequest();r.setBranchId(main);r.setBaseVersion(0L);r.setExpectedDraftVersion(-1L);r.setLoadedRevision((String)s.get("loadedRevision"));r.setOperationId(UUID.randomUUID().toString());r.setCommitMessage("branch baseline");r.setSource("manual");r.setContent(a);r.setExecutedChanges(Collections.singletonList(Collections.singletonMap("kind",(Object)"manual")));head=(String)f.tx.execute(tx->f.service.commit(book,r)).getData().get("commitId");BranchRequest br=new BranchRequest();br.setOperationId(UUID.randomUUID().toString());br.setBranchName("branch-"+UUID.randomUUID());br.setFromCommitId(head);target=((Number)f.tx.execute(tx->f.service.createBranch(book,br)).getData().get("branchId")).longValue();}
    protected void tearDown(){f.close();}
    private Map<String,Object> state(){return f.status(book);}
    private WorkingStateRequest draftRequest(String content){Map<String,Object>s=state();Map<?,?>d=(Map<?,?>)s.get("workingState");WorkingStateRequest r=f.request(book,d==null?-1:((Number)d.get("version")).longValue(),(String)s.get("loadedRevision"),content);r.setBaseCommitId((String)s.get("headCommitId"));r.setBaseVersion(((Number)s.get("version")).longValue());return r;}
    private void draft(String content){assertEquals(200,f.save(book,draftRequest(content)).getCode());}
    private R<Map<String,Object>> checkout(long branch,CheckoutRequest r){return f.tx.execute(tx->f.service.checkout(book,branch,r));}
    private void checkout(long branch){assertEquals(200,checkout(branch,f.checkoutRequest(book,branch)).getCode());}
    private void active(long branch,String content){Map<String,Object>s=state();assertEquals(branch,((Number)s.get("branchId")).longValue());assertEquals(content,s.get("content"));}
    private String savedDraft(long branch){return f.db.queryForObject("select cast(draft_snapshot as char character set utf8mb4) from ai_workbook_working_state where workbook_id=? and branch_id=?",String.class,book,branch);}
    public void testCheckoutAndReturnPreserveSeparateDraftsAndHistory(){draft(b);checkout(target);active(target,a);draft(c);checkout(main);active(main,b);assertEquals(c,savedDraft(target));assertEquals(b,savedDraft(main));assertEquals(head,state().get("headCommitId"));assertEquals(1,f.db.queryForObject("select count(*) from ai_workbook_commit where workbook_id=?",Integer.class,book).intValue());}
    public void testMissingOrForgedCheckoutFieldsDoNotMovePointers(){draft(b);long version=((Number)state().get("workbookVersion")).longValue();for(int mode=0;mode<18;mode++){CheckoutRequest r=f.checkoutRequest(book,target);switch(mode){case 0:r.setCurrentBranchId(null);break;case 1:r.setCurrentBranchId(999L);break;case 2:r.setBaseVersion(null);break;case 3:r.setBaseVersion(999L);break;case 4:r.setBaseCommitId(null);break;case 5:r.setExpectedDraftVersion(null);break;case 6:r.setExpectedDraftVersion(-1L);break;case 7:r.setLoadedRevision(null);break;case 8:r.setLoadedRevision("forged");break;case 9:r.setExpectedWorkbookVersion(null);break;case 10:r.setExpectedWorkbookVersion(999L);break;case 11:r.setTargetVersion(null);break;case 12:r.setTargetVersion(999L);break;case 13:r.setTargetHeadCommitId("forged");break;case 14:r.setExpectedTargetDraftVersion(null);break;case 15:r.setExpectedTargetDraftVersion(0L);break;case 16:r.setTargetLoadedRevision(null);break;case 17:r.setTargetLoadedRevision("forged");break;}assertEquals("field "+mode,409,checkout(target,r).getCode());active(main,b);}assertEquals(version,((Number)state().get("workbookVersion")).longValue());}
    public void testLegacyCheckoutWithoutBindingsFailsClosed(){CheckoutRequest r=new CheckoutRequest();r.setOperationId(UUID.randomUUID().toString());assertEquals(409,checkout(target,r).getCode());active(main,a);}
    public void testNewSourceDraftRejectsPreviouslyCapturedRequest(){CheckoutRequest old=f.checkoutRequest(book,target);draft(b);assertEquals(409,checkout(target,old).getCode());active(main,b);}
    public void testNewerSourceDraftRejectsSameHeadRequest(){draft(b);CheckoutRequest old=f.checkoutRequest(book,target);draft(c);assertEquals(409,checkout(target,old).getCode());active(main,c);}
    public void testCheckoutAwayAndBackInvalidatesOldWorkbookGeneration(){CheckoutRequest old=f.checkoutRequest(book,target);checkout(target);checkout(main);assertEquals(409,checkout(target,old).getCode());active(main,a);}
    public void testDuplicateSuccessfulCheckoutReturnsConflictWithoutAnotherMove(){CheckoutRequest r=f.checkoutRequest(book,target);assertEquals(200,checkout(target,r).getCode());long version=((Number)state().get("workbookVersion")).longValue();assertEquals(409,checkout(target,r).getCode());active(target,a);assertEquals(version,((Number)state().get("workbookVersion")).longValue());}
    public void testTargetDraftMetadataMustMatchWhatWasRead(){CheckoutRequest old=f.checkoutRequest(book,target);checkout(target);draft(b);checkout(main);CheckoutRequest fresh=f.checkoutRequest(book,target);fresh.setExpectedTargetDraftVersion(old.getExpectedTargetDraftVersion());fresh.setTargetLoadedRevision(old.getTargetLoadedRevision());assertEquals(409,checkout(target,fresh).getCode());active(main,a);assertEquals(b,savedDraft(target));}
    public void testTargetBranchVersionMustMatchEvenIfHeadSame(){CheckoutRequest r=f.checkoutRequest(book,target);f.db.update("update ai_workbook_branch set version=version+1 where branch_id=?",target);assertEquals(409,checkout(target,r).getCode());active(main,a);}
    public void testCorruptTargetSnapshotCannotMovePointers(){CheckoutRequest r=f.checkoutRequest(book,target);f.db.update("update ai_workbook_snapshot set content_hash='bad' where commit_id=?",head);assertEquals(422,checkout(target,r).getCode());active(main,a);}
    public void testCorruptTargetDraftCannotMovePointers(){checkout(target);draft(b);checkout(main);CheckoutRequest r=f.checkoutRequest(book,target);f.db.update("update ai_workbook_working_state set content_hash='bad' where workbook_id=? and branch_id=?",book,target);assertEquals(422,checkout(target,r).getCode());active(main,a);}
    public void testTargetDraftBaseMismatchCannotBeLoaded(){checkout(target);draft(b);checkout(main);CheckoutRequest r=f.checkoutRequest(book,target);f.db.update("update ai_workbook_working_state set base_commit_id='bad' where workbook_id=? and branch_id=?",book,target);assertEquals(409,checkout(target,r).getCode());active(main,a);}
    public void testCrossWorkbookAndInactiveTargetReject(){CheckoutRequest r=f.checkoutRequest(book,target);long other=f.seed(a);long foreign=((Number)f.status(other).get("branchId")).longValue();assertTrue(checkout(foreign,r).getCode()!=200);f.db.update("update ai_workbook_branch set status='archived' where branch_id=?",target);assertTrue(checkout(target,r).getCode()!=200);active(main,a);}
    public void testPointerFailureDoesNotConsumeEitherDraft() throws Exception {draft(b);CheckoutRequest r=f.checkoutRequest(book,target);AiWorkbookMapper failing=(AiWorkbookMapper)Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{AiWorkbookMapper.class},(proxy,method,args)->{if(method.getName().equals("updateVersionPointers"))return 0;try{return method.invoke(f.workbooks,args);}catch(InvocationTargetException e){throw e.getCause();}});A1TestFixture.inject(f.service,"workbookMapper",failing);try{checkout(target,r);fail("pointer failure accepted");}catch(IllegalStateException expected){}active(main,b);assertEquals(b,savedDraft(main));}
    public void testMissingActiveBranchInDraftRequestRejects(){WorkingStateRequest r=draftRequest(b);r.setBranchId(null);assertEquals(409,f.save(book,r).getCode());active(main,a);}
    public void testInactiveBranchDraftCannotBeCreatedOrUpdated(){WorkingStateRequest r=draftRequest(b);checkout(target);assertEquals(409,f.save(book,r).getCode());draft(c);checkout(main);WorkingStateRequest inactive=draftRequest(b);inactive.setBranchId(target);inactive.setBaseVersion(0L);inactive.setExpectedDraftVersion(0L);inactive.setLoadedRevision(com.ruoyi.ai.util.ContentHashUtils.sha256(c));assertEquals(409,f.save(book,inactive).getCode());assertEquals(c,savedDraft(target));}
    public void testWorkingStateFieldMatrixPreservesContent(){draft(b);for(int mode=0;mode<8;mode++){WorkingStateRequest r=draftRequest(c);switch(mode){case 0:r.setBaseVersion(null);break;case 1:r.setBaseVersion(999L);break;case 2:r.setBaseCommitId("bad");break;case 3:r.setExpectedDraftVersion(null);break;case 4:r.setExpectedDraftVersion(-1L);break;case 5:r.setExpectedDraftVersion(99L);break;case 6:r.setLoadedRevision("bad");break;case 7:r.setContent(null);break;}assertTrue("draft field "+mode,f.save(book,r).getCode()!=200);assertEquals(b,savedDraft(main));}}
    public void testLegacyVersionedDraftUpdateWithoutHashRemainsCompatible(){draft(b);WorkingStateRequest r=draftRequest(c);r.setLoadedRevision(null);assertEquals(200,f.save(book,r).getCode());active(main,c);}
    public void testCorruptExistingDraftCannotBeOverwrittenEvenWithExplicitVersion(){draft(b);WorkingStateRequest r=draftRequest(c);f.db.update("update ai_workbook_working_state set content_hash='bad' where workbook_id=? and branch_id=?",book,main);assertEquals(422,f.save(book,r).getCode());assertEquals(b,savedDraft(main));}
    public void testExistingDraftWithStaleBaseCannotBeOverwritten(){draft(b);WorkingStateRequest r=draftRequest(c);f.db.update("update ai_workbook_working_state set base_commit_id='bad' where workbook_id=? and branch_id=?",book,main);assertEquals(409,f.save(book,r).getCode());assertEquals(b,savedDraft(main));}
    public void testInvalidJsonObjectDraftsDoNotConsumeCurrentVersion(){draft(b);for(String content:Arrays.asList("bad","[]","null","\"scalar\""," ","{} {}")){assertEquals(422,f.save(book,draftRequest(content)).getCode());assertEquals(b,savedDraft(main));assertEquals(0L,((Number)((Map<?,?>)state().get("workingState")).get("version")).longValue());}}
    public void testIndentedObjectDraftPreservesRawHashZeroAndFalse(){String raw="{\n  \"v\": false,\n  \"n\": 0\n}";assertEquals(200,f.save(book,draftRequest(raw)).getCode());assertEquals(raw,state().get("content"));assertEquals(com.ruoyi.ai.util.ContentHashUtils.sha256(raw),state().get("loadedRevision"));}
    public void testCheckoutAndSaveRespectLeaseAndOwnership(){CheckoutRequest r=f.checkoutRequest(book,target);WorkingStateRequest d=draftRequest(b);f.db.update("insert into ai_agent_lease(workbook_id,run_id,fencing_token,expires_at) values(?,?,1,?)",book,"branch-lease",System.currentTimeMillis()+120000);try{checkout(target,r);fail("lease checkout");}catch(IllegalArgumentException expected){}try{f.save(book,d);fail("lease draft");}catch(IllegalArgumentException expected){}f.db.update("update ai_agent_lease set run_id=null where workbook_id=?",book);SecurityContextHolder.setUserId("2");assertTrue(f.tx.execute(tx->f.service.checkout(book,target,r)).getCode()!=200);assertTrue(f.tx.execute(tx->f.service.saveWorkingState(book,d)).getCode()!=200);f.identity();active(main,a);}
}
